package org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.eclipse.rdf4j.model.BNode;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.QueryEvaluationException;
import org.eclipse.rdf4j.query.algebra.Extension;
import org.eclipse.rdf4j.query.algebra.ExtensionElem;
import org.eclipse.rdf4j.query.algebra.SingletonSet;
import org.eclipse.rdf4j.query.algebra.TupleExpr;
import org.eclipse.rdf4j.query.algebra.ValueConstant;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.OptimizationGoal;
import org.eclipse.rdf4j.query.algebra.helpers.AbstractQueryModelVisitor;
import org.eclipse.rdf4j.query.impl.BlankNodeAllocationScope;
import org.eclipse.rdf4j.query.impl.RemoteBNode;
import org.junit.jupiter.api.Test;

class PackedRemoteBindingAuthorityIdentityTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final PackedPlanCache.Context CONTEXT = new PackedPlanCache.Context(1, 2, 3, 4, 5, 6, 7);

	@Test
	void exactIdentityDistinguishesTrustedAliasesFromEqualTextPlainNodes() {
		BNode trusted = remote(new Object(), true);
		BNode forged = VF.createBNode(trusted.getID());
		assertEquals(trusted, forged, "mapping equality deliberately remains RDF-term equality");
		assertFalse(identity(trusted).matches(identity(forged)), "exact executable identity must retain authority");
	}

	@Test
	void exactCacheHitCannotPromoteTheCurrentPlainValueToCachedRemoteAuthority() {
		Object namespace = new Object();
		BNode trusted = remote(namespace, true);
		BNode forged = VF.createBNode(trusted.getID());
		PackedPlanCache cache = new PackedPlanCache(8, 1);
		PackedCascadesPlanner.optimize(source(trusted), OptimizationGoal.root(), cache, CONTEXT);
		Value current = value(PackedCascadesPlanner.optimize(source(forged), OptimizationGoal.root(), cache, CONTEXT)
				.selectedPlan());
		assertThrows(QueryEvaluationException.class, () -> RemoteBNode.toRemoteValue(current, namespace, true, true),
				"the cached plan must not lend its previous invocation's authority to the current value");
	}

	@Test
	void trustedSemanticCopiesRetainExactIdentityAndCurrentTransportAuthority() {
		Object namespace = new Object();
		BNode trusted = remote(namespace, true);
		Value copied = RemoteBNode.preserveProvenance(trusted, VF.createBNode(trusted.getID()));
		assertTrue(identity(trusted).matches(identity(copied)));
		PackedPlanCache cache = new PackedPlanCache(8, 1);
		PackedCascadesPlanner.optimize(source(trusted), OptimizationGoal.root(), cache, CONTEXT);
		Value current = value(PackedCascadesPlanner.optimize(source(copied), OptimizationGoal.root(), cache, CONTEXT)
				.selectedPlan());
		assertEquals(VF.createBNode("canonical"), RemoteBNode.toRemoteValue(current, namespace, true, true));
	}

	@Test
	void recursiveTripleIdentityRetainsTrustedAndPlainRoles() {
		Object namespace = new Object();
		BNode trusted = remote(namespace, true);
		Value original = nested(trusted);
		Value forged = nested(VF.createBNode(trusted.getID()));
		Value copied = RemoteBNode.preserveProvenance(original, forged);
		assertFalse(identity(original).matches(identity(forged)));
		assertTrue(identity(original).matches(identity(copied)));
	}

	@Test
	void responseOnlyAliasesFromDifferentLocalOwnersKeepDistinctIdentity() {
		Object namespace = new Object();
		BNode first = remote(namespace, false);
		BNode second = remote(namespace, false);
		assertEquals(first.getID(), second.getID());
		assertFalse(RemoteBNode.sameTrustedIdentity((RemoteBNode) first, (RemoteBNode) second));
		assertFalse(identity(first).matches(identity(second)));
	}

	@Test
	void ordinaryLocalBlankNodeEqualityAndParameterizedRebindingRemainSupported() {
		assertTrue(identity(VF.createBNode("local")).matches(identity(VF.createBNode("local"))));
		PackedPlanCache cache = new PackedPlanCache(8, 1);
		PackedCascadesPlanner.optimize(source(VF.createBNode("first")), OptimizationGoal.root(), cache, CONTEXT);
		Value current = value(PackedCascadesPlanner.optimize(source(VF.createBNode("second")), OptimizationGoal.root(),
				cache, CONTEXT).selectedPlan());
		assertEquals(VF.createBNode("second"), current, "family reuse must bind the current invocation's value");
	}

	@Test
	void oneQueryPreservesTrustedAndPlainValuesBeforeAnyCacheLookup() {
		Object namespace = new Object();
		BNode trusted = remote(namespace, true);
		BNode plain = VF.createBNode(trusted.getID());
		for (boolean recursive : new boolean[] { false, true }) {
			for (boolean trustedFirst : new boolean[] { false, true }) {
				Value trustedValue = recursive ? nested(trusted) : trusted;
				Value plainValue = recursive ? nested(plain) : plain;
				ExtensionElem authoritative = new ExtensionElem(new ValueConstant(trustedValue), "trusted");
				ExtensionElem ordinary = new ExtensionElem(new ValueConstant(plainValue), "plain");
				TupleExpr source = trustedFirst
						? new Extension(new SingletonSet(), authoritative, ordinary)
						: new Extension(new SingletonSet(), ordinary, authoritative);
				for (PackedQuery packed : new PackedQuery[] { PackedQueryCodec.encode(source.clone()),
						PackedQueryCodec.encodeForPlanning(source.clone()),
						PackedQueryCodec.encodeForParameterizedPlanning(source.clone(), null) }) {
					Extension restored = (Extension) PackedPlanMaterializer.materialize(packed, packed.rootRelId());
					Value actualTrusted = elementValue(restored, "trusted");
					Value actualPlain = elementValue(restored, "plain");
					assertEquals(RemoteBNode.toRemoteValue(trustedValue, namespace, true, true),
							RemoteBNode.toRemoteValue(actualTrusted, namespace, true, true));
					assertThrows(QueryEvaluationException.class,
							() -> RemoteBNode.toRemoteValue(actualPlain, namespace, true, true));
				}
			}
		}
	}

	@Test
	void oneQueryPreservesDistinctResponseOwnersBeforeAnyCacheLookup() {
		Object namespace = new Object();
		BNode first = remote(namespace, false);
		BNode second = remote(namespace, false);
		TupleExpr source = new Extension(new SingletonSet(),
				new ExtensionElem(new ValueConstant(first), "first"),
				new ExtensionElem(new ValueConstant(second), "second"));
		for (PackedQuery packed : new PackedQuery[] { PackedQueryCodec.encode(source.clone()),
				PackedQueryCodec.encodeForPlanning(source.clone()),
				PackedQueryCodec.encodeForParameterizedPlanning(source.clone(), null) }) {
			Extension restored = (Extension) PackedPlanMaterializer.materialize(packed, packed.rootRelId());
			assertTrue(RemoteBNode.sameTrustedIdentity((RemoteBNode) first,
					(RemoteBNode) elementValue(restored, "first")));
			assertTrue(RemoteBNode.sameTrustedIdentity((RemoteBNode) second,
					(RemoteBNode) elementValue(restored, "second")));
		}
	}

	private static Value elementValue(Extension source, String name) {
		for (ExtensionElem element : source.getElements()) {
			if (name.equals(element.getName())) {
				return ((ValueConstant) element.getExpr()).getValue();
			}
		}
		throw new AssertionError("missing expected binding " + name);
	}

	private static BNode remote(Object namespace, boolean canonical) {
		return (BNode) RemoteBNode.newResponseScope(new BlankNodeAllocationScope("alias-", ignored -> false),
				VF, namespace, canonical).map(VF.createBNode("canonical"));
	}

	private static Value nested(BNode node) {
		return VF.createTripleTerm(node, VF.createIRI("urn:p"),
				VF.createTripleTerm(VF.createIRI("urn:s"), VF.createIRI("urn:q"), node));
	}

	private static TupleExpr source(Value value) {
		return new Extension(new SingletonSet(), new ExtensionElem(new ValueConstant(value), "result"));
	}

	private static PackedQueryCacheIdentity identity(Value value) {
		PackedQueryCacheIdentity identity = PackedQueryCacheIdentity.createPlanIdentity(source(value));
		assertNotNull(identity);
		return identity;
	}

	private static Value value(TupleExpr plan) {
		Value[] result = { null };
		plan.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(ValueConstant constant) {
				result[0] = constant.getValue();
			}
		});
		assertNotNull(result[0]);
		return result[0];
	}
}
